func run(jobs []Job) []Result {
  results := []Result{}
  ch := make(chan Job)
  var wg sync.WaitGroup
  for i := 0; i < 4; i++ {
    go func() {
      for j := range ch { results = append(results, j.Do()); wg.Done() }
    }()
  }
  for _, j := range jobs { wg.Add(1); ch <- j }
  wg.Wait()
  return results
}

