}

func (r *Reconciler) Reconcile(ctx, req) (Result, error) {
  obj := get(req)
  desired := render(obj.Spec)
  if !equal(obj.Status.Observed, desired) { update(desired); return Result{Requeue: true}, nil }
  return Result{}, nil
}

